00042 struct YUVFormatInfo {
00043     YUVFormatInfo(uint32_t planeCount, uint32_t sizeMult, uint32_t sizeDiv, uint8_t bitDepth, uint32_t horizontalDownsample,
00044                   uint32_t verticalDownsample)
00045         : m_planeCount(planeCount), m_sizeMult(sizeMult), m_sizeDiv(sizeDiv), m_bitDepth(bitDepth),
00046           m_horizontalDownsample(horizontalDownsample), m_verticalDownsample(verticalDownsample) {}
00047 
00048     uint32_t m_planeCount;
00049     uint32_t m_sizeMult;
00050     uint32_t m_sizeDiv;
00051     uint8_t m_bitDepth;
00052     uint32_t m_horizontalDownsample;
00053     uint32_t m_verticalDownsample;
00054 };
