00120 bool YUVFormat::FromString(Enum &res, const std::string &str) { return kYUVFormatMap.FindEnum(res, str, YUVFormat::Invalid); }
00121 
00122 YUVFormat::Enum YUVFormat::FromString2(const std::string &str) { return FromString2Helper(FromString, str); }
00123 
00124 bool YUVFormat::ToString(const char **res, Enum type) { return kYUVFormatMap.FindName(res, type, "YUVFormat-ERROR"); }
00125 
00126 const char *YUVFormat::ToString2(Enum val) { return ToString2Helper(ToString, val); }
