00137 YUVDesc::PlaneDesc::PlaneDesc(uint32_t width, uint32_t height, uint32_t stridePixels, uint32_t strideBytes)
00138     : m_width(width), m_height(height), m_stridePixels(stridePixels), m_strideBytes(strideBytes) {}
00139 
00140 // -------------------------------------------------------------------------
00141 
00142 YUVDesc::YUVDesc() : m_format(YUVFormat::Invalid), m_planeCount(0), m_byteSize(0), m_bitDepth(0), m_bitDepthContainer(0) {}
00143 
00144 void YUVDesc::Initialise(YUVFormat::Enum format, uint32_t width, uint32_t height) {
00145     const YUVFormatInfo &info = kFormatInfo[format];
00146 
00147     m_format = format;
00148     m_planeCount = info.m_planeCount;
00149     assert(m_planeCount <= kMaxNumPlanes);
00150 
00151     m_bitDepth = info.m_bitDepth;
00152     m_bitDepthContainer = (m_bitDepth + 7) & ~7;
00153 
00154     const uint8_t byteDepth = GetByteDepth();
00155 
00156     for (uint32_t planeIndex = 0; planeIndex < m_planeCount; ++planeIndex) {
00157         const uint32_t planeWidth =
00158             (planeIndex == 0 || (info.m_horizontalDownsample == 1)) ? width : ((width + 1) / info.m_horizontalDownsample);
00159         const uint32_t planeHeight =
00160             (planeIndex == 0 || (info.m_verticalDownsample == 1)) ? height : ((height + 1) / info.m_verticalDownsample);
00161         m_planeDesc[planeIndex] = PlaneDesc(planeWidth, planeHeight, planeWidth, byteDepth * planeWidth);
00162     }
00163 
00164     m_byteSize = (width * height * info.m_sizeMult) / info.m_sizeDiv;
00165 }
00166 
00167 uint32_t YUVDesc::GetWidth() const { return GetPlaneWidth(0); }
00168 
00169 uint32_t YUVDesc::GetHeight() const { return GetPlaneHeight(0); }
00170 
