00172 
00173 uint32_t *YUVDesc::GetHeightPtr() { return GetPlaneHeightPtr(0); }
00174 
00175 YUVFormat::Enum YUVDesc::GetFormat() const { return m_format; }
00176 
00177 uint8_t YUVDesc::GetBitDepth() const { return m_bitDepth; }
00178 
00179 uint8_t YUVDesc::GetBitDepthContainer() const { return m_bitDepthContainer; }
00180 
00181 uint8_t YUVDesc::GetByteDepth() const { return m_bitDepthContainer >> 3; }
00182 
00183 uint32_t YUVDesc::GetMemorySize() const { return m_byteSize; }
00184 
