00187 uint32_t YUVDesc::GetPlaneWidth(uint32_t planeIndex) const {
00188     assert(planeIndex < kMaxNumPlanes);
00189     return m_planeDesc[planeIndex].m_width;
00190 }
00191 
00192 uint32_t YUVDesc::GetPlaneHeight(uint32_t planeIndex) const {
00193     assert(planeIndex < kMaxNumPlanes);
00194     return m_planeDesc[planeIndex].m_height;
00195 }
00196 
00197 uint32_t *YUVDesc::GetPlaneWidthPtr(uint32_t planeIndex) {
00198     assert(planeIndex < kMaxNumPlanes);
00199     return &m_planeDesc[planeIndex].m_width;
00200 }
00201 
00202 uint32_t *YUVDesc::GetPlaneHeightPtr(uint32_t planeIndex) {
00203     assert(planeIndex < kMaxNumPlanes);
00204     return &m_planeDesc[planeIndex].m_height;
