00206 
00207 uint32_t YUVDesc::GetPlaneStrideBytes(uint32_t planeIndex) const {
00208     assert(planeIndex < kMaxNumPlanes);
00209     return m_planeDesc[planeIndex].m_strideBytes;
00210 }
00211 
00212 uint32_t YUVDesc::GetPlaneStridePixels(uint32_t planeIndex) const {
00213     assert(planeIndex < kMaxNumPlanes);
00214     return m_planeDesc[planeIndex].m_stridePixels;
00215 }
00216 
00217 uint32_t YUVDesc::GetPlaneMemorySize(uint32_t planeIndex) const {
00218     assert(planeIndex < kMaxNumPlanes);
00219     const PlaneDesc &desc = m_planeDesc[planeIndex];
00220     return (desc.m_strideBytes * desc.m_height);
00221 }
00222 
00223 void YUVDesc::GetPlanePointers(uint8_t *memoryPtr, uint8_t **planePtrs, uint32_t *planePixelStrides) const {
00224     // Assumes that the out arrays are the correct size.
00225     for (uint32_t planeIndex = 0; planeIndex < m_planeCount; ++planeIndex) {
00226         planePtrs[planeIndex] = memoryPtr;
00227 
00228         if (planePixelStrides) {
00229             planePixelStrides[planeIndex] = GetPlaneStridePixels(planeIndex);
00230         }
00231 
00232         memoryPtr += GetPlaneMemorySize(planeIndex);
00233     }
00234 }
00235 
00236 void YUVDesc::GetPlanePointers(const uint8_t *memoryPtr, const uint8_t **planePtrs, uint32_t *planePixelStrides) const {
00237     // Assumes that the out arrays are the correct size.
00238     for (uint32_t planeIndex = 0; planeIndex < m_planeCount; ++planeIndex) {
00239         planePtrs[planeIndex] = memoryPtr;
00240 
00241         if (planePixelStrides) {
00242             planePixelStrides[planeIndex] = GetPlaneStridePixels(planeIndex);
00243         }
00244 
00245         memoryPtr += GetPlaneMemorySize(planeIndex);
00246     }
00247 }
